checklist='<div class="guide-grid">'+''.join(f'<article class="guide-card"><label><input type="checkbox" data-guide-check="{id}"><span><h3>{title}</h3><p>{text}</p></span></label></article>' for id,title,text in guide_items)+'</div>'
guide=section('A site brief people can examine','Put purpose, space and delivery on the same page.','<div class="split"><div class="flow"><p class="lead">A strong first brief describes a useful combination and shows how it could operate here.</p><p>Start with the people, their activity and the resource they share. Add a current room inventory, a weekly calendar and a transparent cost scenario. Identify the questions that belong to the property parties and those belonging to each service.</p><p>The brief can grow through demonstrations and real responses. It does not need to describe the whole Aura ecosystem before one useful overlap becomes understandable.</p></div>'+figure('public-decisions-hero')+'</div>')
guide+=section('Optional working prompts','Keep track of what you have explored.','<p class="lead narrow">Use any of these prompts that help. They are suggestions for developing a discussion, rather than an agreed process. Selections stay in this browser and can be exported.</p><p class="source-count" data-guide-count>0 of 10 parts marked</p><div class="progress-track" aria-hidden="true"><span data-guide-progress></span></div>'+checklist+'<div class="actions"><button type="button" class="button" data-guide-export>Export the checklist</button><button type="button" class="button secondary" data-print>Print this guide</button>'+link('downloads/site-brief-template.json','Download the site-brief template','button secondary')+'</div><p class="status" data-guide-status role="status" aria-live="polite"></p>')
guide+=section('A possible discussion pack','What would help someone explore the idea?',table(['Part','Contents'],[('The proposition','A chosen activity mix, intended people, public value and the reason this place helps.'),('The place','Current plan, room inventory, supporting facilities and the resource assumptions.'),('Open design questions','Possible use of space, KYC, timing, people and practical questions still to explore.'),('The resource case','Separate initial capital, recurring costs, proposed income, contributions and unresolved inputs.')])+ '<div class="actions">'+link('overlaps.html','Choose an activity combination','button')+link('capacity.html','Save a capacity scenario','button secondary')+'</div>','paper')
page('guide.html','Build a site brief','From interest<br>to <em>a site brief.</em>','Bring a selected overlap, current room evidence and a working operating scenario into a reviewable proposal.','projects-hero',guide)

