network_cards='<div class="network-list">'+''.join('<article class="network-item"><h3>'+e(r['title'])+'</h3><p>'+e(r['note'])+'</p><div class="actions">'+link(r['url'],'Visit the public work ↗')+(link(r['repository'],'GitHub source ↗') if r.get('repository') else '')+'</div></article>' for r in project_refs)+'</div>'
network=section('Possible connections','A wider system in development.','<div class="split"><div class="flow"><p class="lead">The supplied documents and websites are part of a much larger body of developing work. They offer ideas to explore alongside the possibilities of a Brisbane civic establishment.</p><p>Dunwich is an idea in development, with no confirmed programme there. The cultural-intelligence-node material explores possible computing, cultural and co-operative connections on Minjerribah. The installation, learning, enterprise, care and other material is also developing.</p><p>A published website or repository makes an idea available to examine. It does not make a place, programme, participant or partnership confirmed. Which connections could be useful here remains open.</p></div>'+figure('island-twin')+'</div>')
network+=section('Developing project library','Explore the ideas at their source.',network_cards)
network+=section('What travels between places','A useful result can leave more capability behind.',panels([('Learning and methods','A worked example, training material, a measured result and the correction that improved it.','workforce.html'),('Workloads and services','A defined compute job, a shared project or an agreed support relationship.','economics.html#compute'),('People and relationships','Mentors, peers, cultural collaboration and organisations choosing to work together.','partners.html')]),'paper')
page('network.html','Developing connections','One possibility.<br><em>A wider exploration.</em>','Explore related proposals and source repositories within a system in development, including an unconfirmed Dunwich concept.','island-twin',network)

